LAMP_ASSETS=['assets/game/locations/overworld/lamps/profile.json']+['assets/game/locations/overworld/lamps/lamp_'+side+'_v1.png'+suffix for side in ['south','west','east'] for suffix in ['', '.import']]

def collect(folder,phase):
